mapper.select:
select sc.shop_config_id as shopConfigId, sc.shop_code as shopCode, sc.shop_name as shopName, sc.douyin_account_code as douyinAccountCode, sc.douyin_shop_name as douyinShopName, sc.message_template as messageTemplate, sc.daily_limit as dailyLimit, ( select count(1) from dy_rpa_outreach_task done where done.shop_config_id = sc.shop_config_id and done.completed_time >= curdate() and done.status in ('ordered', 'contacted') ) as dailyCompleted, sc.daily_limit - ( select count(1) from dy_rpa_outreach_task done where done.shop_config_id = sc.shop_config_id and done.completed_time >= curdate() and done.status in ('ordered', 'contacted') ) as dailyRemaining from dy_rpa_outreach_task t inner join dy_rpa_shop_config sc on sc.shop_config_id = t.shop_config_id and sc.status = '0' where t.status = 'pending' and t.attempt_count < t.max_attempts
and sc.shop_code = #{preferredShopCode}
and not exists ( select 1 from dy_rpa_outreach_batch b where b.shop_config_id = sc.shop_config_id and b.status = 'leased' ) and ( select count(1) from dy_rpa_outreach_task done where done.shop_config_id = sc.shop_config_id and done.completed_time >= curdate() and done.status in ('ordered', 'contacted') ) < sc.daily_limit order by t.priority desc, t.task_id asc limit 1

mapper.update:
update dy_rpa_outreach_task set status = 'leased', batch_no = #{batchNo}, lease_token = #{leaseToken}, worker_id = #{workerId}, lease_expire_time = date_add(sysdate(), interval #{leaseMinutes} minute), attempt_count = attempt_count + 1, first_claim_time = ifnull(first_claim_time, sysdate()), update_time = sysdate() where task_id in
#{taskId}
and status = 'pending'

update dy_rpa_outreach_batch
set task_count = #{taskCount}, update_time = sysdate()
where batch_no = #{batchNo}

update dy_rpa_outreach_batch
set lease_expire_time = date_add(sysdate(), interval #{leaseMinutes} minute),
    update_time = sysdate()
where batch_no = #{batchNo}
  and lease_token = #{leaseToken}
  and worker_id = #{workerId}
  and status = 'leased'
  and lease_expire_time > sysdate()

update dy_rpa_outreach_task
set lease_expire_time = date_add(sysdate(), interval #{leaseMinutes} minute),
    update_time = sysdate()
where batch_no = #{batchNo}
  and lease_token = #{leaseToken}
  and worker_id = #{workerId}
  and status = 'leased'

update dy_rpa_outreach_batch
set status = 'released', active_shop_key = null, completed_time = sysdate(), update_time = sysdate()
where batch_no = #{batchNo}
  and lease_token = #{leaseToken}
  and worker_id = #{workerId}
  and status = 'leased'
